{"command": "# Extract stack trace lines for java.lang exception (top most common)
# Search for lines containing "java.lang" and "at " in all log files

python3 << 'PYTHON_EOF'
import re
from collections import defaultdict

# Read all log files
all_log_content = ""
for log_file in ['/app/logs/app_cbmcrw.log', '/app/logs/app_pm0hvs.log', 
                 '/app/logs/app_sdsd8o.log', '/app/logs/app_t273jh.log', 
                 '/app/logs/app_z0wks5.log']:
    with open(log_file, 'r') as f:
        all_log_content += f.read() + "\n"

# Pattern to match stack trace lines: starts with 4 spaces + "at "
# Format: "    at com.example.app.Service2.method2(com.example.app.Service2.java:347)"
stack_trace_pattern = re.compile(r'^\s*at\s+\w+\.\w+\.\w+\.\w+\.\w+\.\w+\.\w+\:\w+:\d+\(\)')

# Find all stack trace lines in all files
all_stack_lines = []
for content in all_log_content.split('\n'):
    lines = content.split('\n')
    for line in lines:
        if re.search(stack_trace_pattern, line):
            # Extract just the stack trace line (without prefix)
            # Format: "    at com.example.app.Service2.method2(com.example.app.Service2.java:347)"
            # We need to keep the full line as stack trace
            all_stack_lines.append(line)

# Group stack traces by exception class
# Top 3 exceptions:
# 1. java.lang (90 occurrences)
# 2. javax.servlet (30 occurrences)
# 3. java.util (30 occurrences)

# Extract stack traces for each top exception class
# From the log content, find lines containing the exception class AND "at " pattern

# For java.lang - search lines containing "java.lang" and "at "
java_lang_stack_lines = []
for line in all_stack_lines:
    if 'java.lang' in line and 'at ' in line:
        # Extract the line content (full stack trace line)
        java_lang_stack_lines.append(line)

# For javax.servlet
javax_servlet_stack_lines = []
for line in all_stack_lines:
    if 'javax.servlet' in line and 'at ' in line:
        javax_servlet_stack_lines.append(line)

# For java.util
java_util_stack_lines = []
for line in all_stack_lines:
    if 'java.util' in line and 'at ' in line:
        java_util_stack_lines.append(line)

# Build stack trace entries
stack_traces = []

# Java.lang stack trace (top exception)
for line in java_lang_stack_lines[:3]:
    stack_traces.append({
        "exception_class": "java.lang",
        "stack_trace": line
    })

# javax.servlet stack trace
for line in javax_servlet_stack_lines[:3]:
    stack_traces.append({
        "exception_class": "javax.servlet",
        "stack_trace": line
    })

# java.util stack trace
for line in java_util_stack_lines[:3]:
    stack_traces.append({
        "exception_class": "java.util",
        "stack_trace": line
    })

# Update incident_report.json
import json
incident_report = {
    "summary": {
        "total_files": 5,
