        {"class_name": "javax.servlet", "count": 30, "percentage": 12.6},
        {"class_name": "java.util", "count": 30, "percentage": 12.6},
        {"class_name": "java.io", "count": 27, "percentage": 11.3},
        {"class_name": "java.net", "count": 23, "percentage": 9.7},
        {"class_name": "java.sql", "count": 20, "percentage": 8.4},
        {"class_name": "java.security", "count": 18, "percentage": 7.6}
    ],
