            "stack_trace": "    at com.example.app.Service2.method2(com.example.app.Service2.java:347)\n    at com.example.app.Controller.handle(Controller.java:85)\n    at javax.servlet.http.HttpServlet.service(HttpServlet.java:0)\n"
        },
